struct Params {
  threshold: f32, // @default 1.2  Linear radiance where bloom starts.
  knee: f32, // @default 0.8  Softness of the threshold.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let color = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb;
  let brightness = max(color.r, max(color.g, color.b));
  let soft = clamp(brightness - params.threshold + params.knee, 0.0, 2.0 * params.knee);
  let weight = max(soft * soft / (4.0 * params.knee + 1e-4), brightness - params.threshold) / max(brightness, 1e-4);
  return vec4f(color * weight, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  threshold: f32,
  feather: f32,
  invert: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let s = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  /* Single-channel depth (r32float, T959) reads .r; colour maps read luma (T974's rule). */
  let d = select(dot(s.rgb, vec3f(0.2126, 0.7152, 0.0722)), s.r, s.g + s.b < 1e-6);
  var matte = smoothstep(params.threshold - params.feather, params.threshold + params.feather, d);
  matte = select(matte, 1.0 - matte, params.invert > 0.5);
  return vec4f(matte, matte, matte, matte);
}

parameters.kernel:
struct Params {
  unproject: f32,
  fov: f32,
  inverseDepth: f32,
  near: f32,
  far: f32,
  displace: f32,
}

fn decodeDepth(sample: f32, near: f32, far: f32, inverse: f32) -> f32 {
  /* inverse (ML disparity-like): bright = close; metres via the harmonic mix.
     linear: metres via the plain mix. Both span [near, far]. */
  let s = clamp(sample, 0.0, 1.0);
  let inv = 1.0 / mix(1.0 / far, 1.0 / near, s);
  let lin = mix(near, far, s);
  return select(lin, inv, inverse > 0.5);
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let near = max(ctx.params.near, 1.0e-3);
  let far = max(ctx.params.far, near + 1.0e-3);

  /* The generator may carry more capacity than the grid (a published resolution knob
     moves cols/rows under a fixed count): every index past the grid parks far outside
     the frustum and draws nothing. */
  let cells = ctx.dim.cols * ctx.dim.rows;
  if (ctx.index >= cells) {
    q.position = vec3f(0.0, -10000.0, 0.0);
    q.tint = vec4f(0.0);
    q.depthN = 0.0;
    return q;
  }

  /* The grid generator laid points across the clip square; that xy IS the depth map's
     uv in fieldAt's own convention — one mapping, shared. */
  let sample = fieldAt(vec3f(p.position.xy, 0.0));
  /* Single-channel maps (the depth node's r32float, T959) read .r; colour depth
     visualisations (turbo, viridis) read luma; grey maps agree under both. */
  let value = select(dot(sample.rgb, vec3f(0.2126, 0.7152, 0.0722)), sample.r, sample.g + sample.b < 1e-6);
  let metres = decodeDepth(value, near, far, ctx.params.inverseDepth);
  /* T973: the decoded depth rides its own attribute to the paint kernel — the heatmap
     is a second READOUT of the axis a 2D projection hides, not a decoration. 0 = near. */
  q.depthN = clamp((metres - near) / (far - near), 0.0, 1.0);

  if (ctx.params.unproject < 0.5) {
    /* HEIGHTFIELD: near pops toward the viewer, scaled by displace. */
    let relief = (1.0 - (metres - near) / (far - near)) * ctx.params.displace;
    q.position = vec3f(p.position.xy, relief);
    return q;
  }

  /* UNPROJECTION: ray through the pixel, scaled by metres, recentred about origin. */
  let dims = vec2f(textureDimensions(fieldTexture, 0));
  let aspect = dims.x / max(dims.y, 1.0);
  let ty = tan(ctx.params.fov * 0.00872664626);  /* radians(fov) / 2 */
  let ray = vec3f(p.position.x * ty * aspect, p.position.y * ty, -1.0);
  let mid = (near + far) * 0.5;
  let scaled = ray * metres * ctx.params.displace;
  q.position = vec3f(scaled.xy, scaled.z + mid * ctx.params.displace);
  return q;
}

struct Params {
  gain: f32,
  heat: f32,
}

/* T973 — a thermal readout of depth: near burns white-hot through orange, far cools
   through magenta into deep blue. Analytic, so no second texture is needed (a point
   kernel has ONE field input, and it is carrying the colour map). */
fn thermal(t: f32) -> vec3f {
  let n = clamp(1.0 - t, 0.0, 1.0);
  return vec3f(
    smoothstep(0.0, 0.45, n),
    smoothstep(0.5, 0.9, n) * 0.8,
    smoothstep(0.0, 0.2, n) * (1.0 - smoothstep(0.25, 0.6, n)) + smoothstep(0.85, 1.0, n),
  );
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let cols = max(ctx.dim.cols, 2u);
  let rows = max(ctx.dim.rows, 2u);
  if (ctx.index >= cols * rows) {
    q.tint = vec4f(0.0);
    return q;
  }
  let u = f32(ctx.dim.i) / f32(cols - 1u);
  let v = f32(ctx.dim.j) / f32(rows - 1u);
  /* fieldAt speaks clip coordinates; the grid generator's layout inverted nothing, so
     the same mapping the carve kernel rode puts the colour texel under its point. */
  let colour = fieldAt(vec3f(u * 2.0 - 1.0, v * 2.0 - 1.0, 0.0));
  /* T973: photographic at heat 0, thermal at 1 — and the middle is the point: the
     source's own colour with depth bleeding through, one knob rather than a mode. */
  let blended = mix(colour.rgb, thermal(p.depthN), clamp(ctx.params.heat, 0.0, 1.0));
  /* §T977 follow-up: the field's ALPHA is honoured as COVERAGE, premultiplied — the
     colour carries the coverage, the scene renderer's own additive convention, and the
     same rule this kernel already applies at its two parked exits (tint = vec4f(0.0)).
     A masked colour map (DepthCut) now actually darkens the motes it cut. CLAMPED,
     because coverage is [0, 1] by meaning: an additive composite upstream SUMS alphas
     (measured - a lit disc over an opaque bed reads a = 2), and honouring that literally
     would double the rgb of every such point. With the clamp, any map that is
     opaque-or-over is bit-identical to the pre-fix output. */
  let cover = clamp(colour.a, 0.0, 1.0);
  q.tint = vec4f(blended * ctx.params.gain * cover, cover);
  return q;
}

parameters.source:
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  grid: vec2f,
  amount: f32,
  rate: f32,
  seed: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

// @use grid
/*
 * Integer avalanche (the "lowbias32" family), and INTEGER on purpose: a float hash built
 * on fract(sin(x)) is a different number on every driver, and §V44's sibling promise — a
 * seeded look replays identically — would be a per-machine accident. u32 shifts and
 * multiplies are exact everywhere WGSL runs.
 */
fn hashU(value: u32) -> f32 {
  var x = value;
  x = x ^ (x >> 16u);
  x = x * 0x7feb352du;
  x = x ^ (x >> 15u);
  x = x * 0x846ca68bu;
  x = x ^ (x >> 16u);
  return f32(x & 0x00ffffffu) / 16777216.0;
}

/* Sample this cell, displaced along x and WRAPPED INSIDE IT — the one rule every
   degradation obeys, because a tear or a fringe that crossed a seam would read as a
   broken TILING rather than as a broken monitor. The +4.0 is there because fract() of a
   negative is not the wrap we want and every shove is signed. */
fn tap(cell: GridCell, dx: f32) -> vec4f {
  let local = vec2f(fract(cell.local.x + dx + 4.0), cell.local.y);
  return textureSampleLevel(inputTexture, inputSampler, cell.origin + (local * cell.size), 0.0);
}

/*
 * A BURST SLOT — the envelope, and the whole of what changed in pass 3.
 *
 * Each slot is an independent, deterministic pulse train on ONE cell: a period in frames,
 * a lifetime of a few frames, and a per-cycle roll that decides whether this cycle fires
 * at all. A cell's phase inside its own slot is hashed from its index, so thirty-six cells
 * on the same slot are thirty-six unsynchronised trains rather than one flashbulb.
 *
 * Returns the burst's AGE in frames, or -1 when the slot is quiet.
 *
 * The periods are co-prime frame counts, so two slots on one cell realign only every
 * few hundred frames and three of them effectively never. That is what "multiple random
 * glitches" needs and a single tick cannot give: several short events in flight at
 * different phases.
 */
fn slot(index: u32, seed: u32, salt: u32, period: f32, life: f32, chance: f32, frame: f32) -> f32 {
  /* Per-cell phase, so the wall does not pulse in unison. */
  let shifted = frame + (hashU((index * 7919u) ^ salt) * period);
  let cycle = floor(shifted / period);
  let age = shifted - (cycle * period);
  if (age >= life) { return -1.0; }
  if (hashU((index * 1013u) + (seed * 6151u) + salt + (u32(cycle) * 3571u)) >= chance) { return -1.0; }
  return age;
}

/* Co-prime frame periods. Nothing here shares a factor with anything else here. */
const TEAR_A: f32 = 17.0;
const TEAR_B: f32 = 23.0;
const TEAR_C: f32 = 31.0;
const SNOW_A: f32 = 13.0;
const SNOW_B: f32 = 19.0;
const DROP_P: f32 = 47.0;

/*
 * LIFETIMES, in frames, and they are the owner's note made numeric. A tear that lasts two
 * or three frames at 60 fps is 33-50 ms — a flicker you catch rather than a state you
 * watch. Snow is shorter still. A DROPOUT is the exception and holds for a fifth of a
 * second, because it is not damage: it is the cell briefly becoming a different picture,
 * and a two-frame version of that reads as a dropped frame rather than as an idea.
 */
const TEAR_LIFE: f32 = 3.0;
/*
 * FOUR, and the previous value was the owner's whole complaint: "the static noise in the
 * glitch animation is like just ONE FRAME — that looks not well blended". It literally
 * was. The second snow train ran at SNOW_LIFE - 1, so at SNOW_LIFE = 2 it was a
 * single-frame flash — and a single frame does not read as texture, it reads as a POP.
 * The tears were given 2-3 frames for exactly this reason and the static never got the
 * same treatment. At 4 and 3 it lasts long enough to be seen as grain.
 *
 * SNOW_SHARE comes down with it (0.35 -> 0.18) so the DUTY CYCLE barely moves: life/period
 * x chance was (2/13 + 1/19) x 0.35 = 0.073 and is now (4/13 + 3/19) x 0.18 = 0.084. A
 * longer event that fires proportionally less often is the whole trade; leaving the share
 * alone would have doubled the amount of static on the wall.
 */
const SNOW_LIFE: f32 = 4.0;
const DROP_LIFE: f32 = 12.0;

/* Relative rarity. A tear is the wall's ordinary weather; snow is an interruption; a
   dropout is an EVENT, because it changes what the cell is a picture OF. */
/*
 * How deep the grain modulates what is already there. Bounded above by construction (see
 * the SNOW branch), so this is a texture depth and not a clipping risk.
 *
 * 0.30, down from 0.45, on the owner's "too bright" a second time — and it is the
 * SECOND half of that repair, not the whole of it: the brightening was the silhouette
 * term (see the SNOW branch), and dropping the depth without deleting that would have
 * been another dimmer wrong picture.
 *
 * It stays modest for the RECOLORIZER's sake too: a Lookup turns luminance into a palette
 * position, so a deep luminance grain walks the whole palette between neighbouring texels
 * and monochrome noise arrives as multicoloured confetti (§V853). Measured after this
 * change, chroma across a snowing cell moves less than the clean cell's, so the grain is
 * staying inside one region of the palette.
 */
const SNOW_DEPTH: f32 = 0.3;

const TEAR_SHARE: f32 = 0.55;
const SNOW_SHARE: f32 = 0.18;
const DROP_SHARE: f32 = 0.30;

fn luma(rgb: vec3f) -> f32 {
  return dot(rgb, vec3f(0.2126, 0.7152, 0.0722));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let dims = vec2f(textureDimensions(inputTexture));
  let texel = vec2i(clamp(uv * dims, vec2f(0.0), dims - vec2f(1.0)));
  let here = textureLoad(inputTexture, texel, 0);
  if (params.amount <= 0.0) { return vec4f(here.rgb, 1.0); }

  let cell = gridCellAt(uv, params.grid);
  let index = u32(cell.index);
  let seed = u32(clamp(params.seed, 0.0, 65535.0));
  /* FRAMES, not seconds: an event two frames long has to be counted in the unit it is two
     of. absFrame is the deterministic frame count the transport supplies (§V44) — never a
     wall clock. Rate stretches or compresses every period together, so the whole wall
     speeds up as one instrument. max(0.25) keeps the trains turning at Rate 0. */
  let frame = frameU.absFrame * max(0.25, params.rate);
  let tick = u32(frame);

  /* THE AUDIO GATE: this cell's own centre texel. Bright cells are dealt in first, so a
     source that responds to the music makes the damage chase the beat across the wall. */
  let middle = vec2i(clamp((cell.origin + (0.5 * cell.size)) * dims, vec2f(0.0), dims - vec2f(1.0)));
  let lit = clamp(luma(textureLoad(inputTexture, middle, 0).rgb), 0.0, 1.0);
  let base = clamp(params.amount * (0.2 + (1.8 * lit)), 0.0, 1.0);

  /* THREE TEAR TRAINS, TWO SNOW TRAINS, ONE DROPOUT — all independent, all per cell. */
  let tearAge = max(
    slot(index, seed, 101u, TEAR_A, TEAR_LIFE, base * TEAR_SHARE, frame),
    max(
      slot(index, seed, 211u, TEAR_B, TEAR_LIFE - 1.0, base * TEAR_SHARE, frame),
      slot(index, seed, 307u, TEAR_C, TEAR_LIFE, base * TEAR_SHARE, frame)));
  let snowAge = max(
    slot(index, seed, 409u, SNOW_A, SNOW_LIFE, base * SNOW_SHARE, frame),
    slot(index, seed, 521u, SNOW_B, SNOW_LIFE - 1.0, base * SNOW_SHARE, frame));
  let dropAge = slot(index, seed, 631u, DROP_P, DROP_LIFE, base * DROP_SHARE, frame);

  /* EXCLUSIVE, rarest first. One thing per cell per frame, on purpose: at 6x6 a cell is a
     couple of thousand pixels and a tear under snow is mud. The variety is in WHICH cells
     and WHICH kind, and it is asserted. */
  if (dropAge >= 0.0) {
    /* DROPOUT — the background falls away. Alpha arrived here as the MATTE, packed into
       the picture before the ring (see the component's pack node), so it has been delayed
       by exactly the same number of frames as the colour it belongs to: a cell holding a
       moment from a second ago drops the background of THAT moment, not of now. */
    return vec4f(here.rgb * clamp(here.a, 0.0, 1.0), 1.0);
  }

  if (snowAge >= 0.0) {
    /*
     * SNOW — and this branch has been rebuilt twice, both times at the cause.
     *
     * WHAT IT LOOKED LIKE WHEN IT WAS WRONG: the owner photographed a two-cell block of
     * full-intensity multicoloured confetti with none of the picture left in it. Three
     * separate faults, none of them a level:
     *
     *  1. IT REPLACED THE PICTURE. mix(silhouette, grain, 0.65) writes a value that owes
     *     almost nothing to what was there, so a cell stopped being a picture. Static has
     *     to RIDE the image — that is the difference between static and a dropout, and
     *     this component already has a dropout.
     *  2. IT CAME OUT CHROMATIC, and not because the grain was. The grain is monochrome
     *     here and always was; the CONFETTI is made downstream, by the recolorizer. A
     *     Lookup maps luminance to a palette position, so a full-swing luminance grain
     *     walks the whole palette between adjacent texels and monochrome noise arrives on
     *     screen as per-pixel colour garbage. The fix is at this end: keep the luminance
     *     excursion small enough that the palette index barely moves, and the same noise
     *     reads as grain instead.
     *  3. IT WAS TOO BIG AND TOO SOLID. A whole cell of it is a rectangle, and a rectangle
     *     is a graphic, not a fault. It is banded now — a few scanline bands per burst —
     *     so it reads as a monitor breaking up rather than as a filled shape.
     *
     * MULTIPLICATIVE, AND HIGHLIGHT-PROTECTED (§V833/§V838). The output is bounded by
     * crushed * (1 + SNOW_DEPTH), and the weight is already ~0 wherever the pixel is
     * bright — so it cannot reach the clip BY CONSTRUCTION, not by tuning. The owner's
     * "it oversteers, overflows" was literal: it was clipping to flat white, and a lower
     * amount would only have made a dimmer wrong picture. The gate asserts the property
     * rather than the number: zero pixels at 1.0 anywhere in a snowing wall.
     *
     */
    let grain = hashU((u32(texel.x) * 73856093u) ^ (u32(texel.y) * 19349663u) ^ (tick * 83492791u) ^ seed);
    /* SCANLINE BANDS, not the whole cell: only some of them break up on a given burst. */
    let bandCount = 5.0 + floor(hashU((index * 5501u) + (tick * 79u) + seed) * 7.0);
    let bandIndex = u32(floor(cell.local.y * bandCount));
    let banded = select(0.35, 1.0, hashU((bandIndex * 2237u) + (index * 91u) + (tick * 397u) + seed) < 0.45);
    /*
     * GRAIN ON THE PICTURE. Two things were removed here, and BOTH were measured before
     * being touched, because "too bright" had already survived one repair.
     *
     * 1. THE SILHOUETTE LIFT. mix(base, step(0.35, base), 0.25) raised every pixel above
     *    the threshold by 0.25 x (1 - base) — a flat +0.10 on a bright cell before any
     *    grain existed. Measured: a snowing cell's mean read 0.7315 against the clean
     *    cell's 0.6853. It was never snow's job; Crush is a published knob with a level
     *    node behind it, and a second hidden discontinuous threshold inside one
     *    degradation is how a control surface stops being trustworthy. Deleted, not
     *    reduced.
     *
     * 2. THE DESATURATION. Writing luma into all three channels made the cell a GREY
     *    PATCH — the owner's "out of place" — and it also made it read brighter for a
     *    reason no amount of level-tweaking would have fixed: the sink's transfer is
     *    concave, so luma-of-encoded is not encode-of-luma, and a monochrome cell at
     *    IDENTICAL linear luminance measures 0.7042 encoded against a colour cell's
     *    0.6853. The picture was not brighter; it had stopped being the picture. So the
     *    grain now rides the colour instead of replacing it, which is what film grain is.
     *
     * §V853 was the third suspect and the same measurement CLEARED it: chroma after the
     * palette went 0.546 -> 0.540, DOWN. The lookup was not amplifying grain into a
     * dimension it lacked.
     *
     * What is left is a symmetric multiplicative modulation, so its expected shift in
     * LINEAR luminance is zero by construction — measured at 0.4841 -> 0.4842, and that is
     * what the gate asserts. Every pixel of a snowing cell is therefore a positive SCALING
     * of the pixel that was there, which is also how the gate tells snow from a tear (a
     * tear moves pixels) and from a dropout (which zeroes them).
     */
    /*
     * The weight is keyed on the PEAK CHANNEL, not on luminance, and that is a correctness
     * fix rather than a nicety: clipping happens per channel, so protection has to be
     * measured per channel. Keyed on luma, a pixel at luma 0.5 could still carry a red of
     * 0.95, get the full grain because its luma looked safe, and clamp — measured, that
     * pushed 7005 pixels onto the sink's ceiling against a clean frame's 3456. Keyed on
     * the peak, the product peak x (1 + SNOW_DEPTH x weight(peak)) tops out around 0.9
     * across the whole range, so nothing can reach the clamp at all.
     */
    let peak = max(here.r, max(here.g, here.b));
    let weight = (1.0 - smoothstep(0.30, 0.92, peak)) * banded;
    let value = here.rgb * (1.0 + (SNOW_DEPTH * weight * ((grain * 2.0) - 1.0)));
    return vec4f(value, 1.0);
  }

  if (tearAge >= 0.0) {
    /*
     * TEAR — bands shove sideways with an RGB fringe riding the same displacement.
     *
     * PASS 3 CHANGED THE ENVELOPE, not the mechanism. Every one of these numbers now
     * re-deals on the FRAME rather than being held for a whole tick: a burst is two or
     * three frames long and the bands jump within it, which is what a glitch looks like.
     * Held for a tick — the pass-2 design — it was one clean state sitting there for half
     * a second, and the owner's verdict was that it read as slow and simplified.
     */
    let strength = params.amount * (0.35 + (0.65 * hashU((index * 337u) + (tick * 61u) + seed)));
    let bands = 4.0 + floor(hashU((index * 977u) + (tick * 131u) + seed) * 12.0);
    let band = u32(floor(cell.local.y * bands));
    let shove = (hashU((band * 1471u) + (index * 29u) + (tick * 523u) + seed) - 0.5) * 0.7 * strength;
    let split = 0.06 * strength;
    let mid = tap(cell, shove);
    let red = tap(cell, shove + split);
    let blue = tap(cell, shove - split);
    return vec4f(red.r, mid.g, blue.b, 1.0);
  }

  return vec4f(here.rgb, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  grid: vec2f,
  mode: f32,
  rate: f32,
  seed: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

// @use grid
/*
 * Integer avalanche (the "lowbias32" family), and INTEGER on purpose: a float hash built
 * on fract(sin(x)) is a different number on every driver, and §V44's sibling promise — a
 * seeded look replays identically — would be a per-machine accident. u32 shifts and
 * multiplies are exact everywhere WGSL runs.
 */
fn hashU(value: u32) -> f32 {
  var x = value;
  x = x ^ (x >> 16u);
  x = x * 0x7feb352du;
  x = x ^ (x >> 15u);
  x = x * 0x846ca68bu;
  x = x ^ (x >> 16u);
  return f32(x & 0x00ffffffu) / 16777216.0;
}

/* Sample this cell, displaced along x and WRAPPED INSIDE IT — the one rule every
   degradation obeys, because a tear or a fringe that crossed a seam would read as a
   broken TILING rather than as a broken monitor. The +4.0 is there because fract() of a
   negative is not the wrap we want and every shove is signed. */
fn tap(cell: GridCell, dx: f32) -> vec4f {
  let local = vec2f(fract(cell.local.x + dx + 4.0), cell.local.y);
  return textureSampleLevel(inputTexture, inputSampler, cell.origin + (local * cell.size), 0.0);
}

const SHOT_ANGLES: f32 = 4.0;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let cell = gridCellAt(uv, params.grid);
  let index = cell.index;
  let seed = u32(clamp(params.seed, 0.0, 65535.0));
  let mode = i32(params.mode + 0.5);

  var delay = 0.0;
  if (mode == 1) {
    /* ORDERED — the cascade. Reading order, oldest at the bottom right. */
    delay = index / cell.last;
  } else if (mode == 2) {
    /* RANDOM — every cell its own moment, held. Seeded, so it is a LOOK, not noise. */
    delay = hashU((u32(index) * 1973u) + (seed * 9277u));
  } else if (mode == 3) {
    /*
     * SWEEP — the owner's "freeze that wanders through".
     *
     * Each cell's delay RAMPS, so it looks one frame further back every frame: at
     * Rate 1.0 (with Spread 1) that is exactly one ring-frame per rendered frame, and
     * the cell holds STILL while the world moves on. The phase offset per cell means
     * they wrap at different times, so the wall refreshes as a rolling wave rather than
     * all at once. Below 1.0 the held frame plays in slow motion; above it, backwards.
     */
    delay = fract((index / cell.count) + (frameU.absTime * params.rate));
  } else if (mode == 4) {
    /*
     * SHOTS — several angles of one scene, cut on a clock.
     *
     * Cells are dealt to SHOT_ANGLES groups by the seeded hash and every group holds one
     * rung of the delay ladder; the ladder rotates one rung per tick, so the whole wall
     * re-cuts at once and then holds. Distinct from RANDOM, which never re-cuts, and from
     * SWEEP, which never holds a whole group together.
     */
    let angle = floor(hashU((u32(index) * 6151u) + (seed * 1543u)) * SHOT_ANGLES);
    let turn = floor(frameU.absTime * max(0.0, params.rate));
    delay = ((angle + turn) % SHOT_ANGLES) / (SHOT_ANGLES - 1.0);
  }
  /* mode 0 — UNIFORM — falls through at 0.0: every cell reads the newest recorded frame,
     so the wall is the plain tiling and the scan is a no-op you can see (§V147's shape). */

  return vec4f(delay, delay, delay, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  grid: vec2f,
  amount: f32,
  rate: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

// @use grid
/*
 * Integer avalanche (the "lowbias32" family), and INTEGER on purpose: a float hash built
 * on fract(sin(x)) is a different number on every driver, and §V44's sibling promise — a
 * seeded look replays identically — would be a per-machine accident. u32 shifts and
 * multiplies are exact everywhere WGSL runs.
 */
fn hashU(value: u32) -> f32 {
  var x = value;
  x = x ^ (x >> 16u);
  x = x * 0x7feb352du;
  x = x ^ (x >> 15u);
  x = x * 0x846ca68bu;
  x = x ^ (x >> 16u);
  return f32(x & 0x00ffffffu) / 16777216.0;
}

/* Sample this cell, displaced along x and WRAPPED INSIDE IT — the one rule every
   degradation obeys, because a tear or a fringe that crossed a seam would read as a
   broken TILING rather than as a broken monitor. The +4.0 is there because fract() of a
   negative is not the wrap we want and every shove is signed. */
fn tap(cell: GridCell, dx: f32) -> vec4f {
  let local = vec2f(fract(cell.local.x + dx + 4.0), cell.local.y);
  return textureSampleLevel(inputTexture, inputSampler, cell.origin + (local * cell.size), 0.0);
}

/* Slow against everything else on the wall: one pass every ~7.7 s at Rate 1. The whole
   point of a sweep is that you wait for it. */
const SWEEP_HZ: f32 = 0.13;
/* Half-width, in frame widths. 0.22 puts the band across about two cells of a 6-wide wall
   — wide enough to read as a front travelling, narrow enough to leave somewhere clean. */
const SWEEP_HALF_WIDTH: f32 = 0.22;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let dims = vec2f(textureDimensions(inputTexture));
  let texel = vec2i(clamp(uv * dims, vec2f(0.0), dims - vec2f(1.0)));
  let here = textureLoad(inputTexture, texel, 0);
  if (params.amount <= 0.0) { return here; }

  let centre = fract(frameU.absTime * SWEEP_HZ * max(0.05, params.rate));
  let distance = abs(uv.x - centre);
  /* Wrapped, so the band leaves the right edge and arrives at the left. */
  let wrapped = min(distance, 1.0 - distance);
  let band = 1.0 - smoothstep(0.0, SWEEP_HALF_WIDTH, wrapped);
  if (band <= 0.0) { return here; }

  let cell = gridCellAt(uv, params.grid);
  /* 0.12 of a CELL width at full Chroma, measured against the picture rather than
     chosen: at 0.05 the fringe was under two texels on a 6-wide wall and did not read. */
  let shift = 0.12 * params.amount * band;
  let red = tap(cell, shift);
  let blue = tap(cell, -shift);
  return vec4f(red.r, here.g, blue.b, here.a);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  amount: f32,        // @default 1  how much pastel stroke texture the shapes carry — 0 is flat cut paper
  seed: f32,          // @default 3  which meadow: every whole number is a different arrangement
  grass: f32,         // @default 150  grass blades leaning in from the frame edge
  flowers: f32,       // @default 18  flower heads on their stems
  flowerSize: f32,    // @default 1  scale of the pom-pom heads
  reach: f32,         // @default 0.6  how far the plants lean in toward the sky's centre, 0 to 1
  wind: f32,          // @default 0.6  how hard blades and stems sway
  clouds: f32,        // @default 0.35  cloud cover, 0 clear to 1 overcast
  boil: f32,          // @default 8  times a second the hand-drawn strokes are redrawn — 0 holds them still
  fps: f32,           // @default 8  stop-motion rate: the plants move only this many times a second — 0 is smooth
  stroke: f32,        // @default 1  size of the pastel strokes
  spin: f32,          // @default 0.02  slow turn of the whole view, radians a second
  lookX: f32,         // @default 0  where in the sky you look, -1 left to 1 right — drag the POV pad
  lookY: f32,         // @default 0  where in the sky you look, -1 down to 1 up
  parallax: f32,      // @default 1  how much faster near plants move than far sky and clouds — 0 moves everything together
  wander: f32,        // @default 0.1  the view drifts around the sky by itself, this far
  skyColor: vec3f,    // @default [0.012, 0.2, 0.55]  the deep blue at the frame edges
  hazeColor: vec3f,   // @default [0.05, 0.42, 0.72]  the lighter blue toward the centre
  petalColor: vec3f,  // @default [0.96, 0.32, 0.03]  the lit rim of the flower heads
  heartColor: vec3f,  // @default [0.06, 0.006, 0.012]  the dark core of the flower heads
  accentColor: vec3f, // @default [0.98, 0.62, 0.02]  the second kind of flower head mixed into the first
  leafDarkColor: vec3f,  // @default [0.004, 0.02, 0.008]  leaves in shadow, the near-black silhouettes
  leafColor: vec3f,      // @default [0.08, 0.32, 0.04]  the body colour of the leaves
  leafLightColor: vec3f, // @default [0.42, 0.62, 0.06]  leaves catching the sun
  cloudColor: vec3f,  // @default [0.95, 0.9, 0.76]  the lit side of the clouds
  glowColor: vec3f,   // @default [1.0, 0.8, 0.5]  the sun's glow in the sky
  glow: f32,          // @default 0  how strongly the sun glows through, 0 to 1
  leafWidth: f32,     // @default 1  leaf width — under 1 needles and corn, over 2 jungle leaves
  leafBend: f32,      // @default 1  how far leaves curl — near 0 they stand straight like stalks
  leafShape: f32,     // @default 0  0 a grass blade tapering to its tip, 1 a broad leaf pointed at both ends with a midrib
  headStretch: f32,   // @default 1  1 a round pom-pom, above 2 a long tassel hanging past the stem
  headPetals: f32,    // @default 0  0 a fuzzy pom-pom, 1 a sunflower: a ring of petals round a dark disc
  fringe: f32,        // @default 0  0 smooth leaves, 1 conifer trunks: sprays of needled branches all along each one
  trunkColor: vec3f,  // @default [0.06, 0.03, 0.015]  the bark showing down the middle of a fringed trunk
  timeOfDay: f32,     // @default 0.5  where the day starts: 0 midnight, 0.25 dawn, 0.5 noon, 0.75 dusk
  dayLength: f32,     // @default 60  seconds for one whole day and night — 0 holds the time of day still
  dayAmount: f32,     // @default 1  how far the cycle changes the light — 0 keeps every scene at its own noon
  zoom: f32,          // @default 1  dolly in (above 1) or out: near plants grow faster than the far sky
  zoomPulse: f32,     // @default 0  the view breathes in and out by this much
  zoomSpeed: f32,     // @default 0.35  how fast it breathes, radians a second
  roll: f32,          // @default 0  the view's turn, radians — wire an integrated speed here for smooth rotation
  wanderSpeed: f32,   // @default 1  how fast the view drifts round the sky
  windGain: f32,      // @default 1  multiplies each scene's own wind
  gust: f32,          // @default 0.3  waves of wind sweeping round the frame, bending everything one way
  grow: f32,          // @default 1  how far the plants have grown: 0 bare, 1 the scene's own size, 2 overgrown — they sprout one after another
  lifespan: f32,      // @default 0  seconds each plant lives before it withers and a different one sprouts — 0 forever
  depthHaze: f32,     // @default 0.4  far plants fade into the sky's haze, near ones stay strong
  reeds: f32,         // @default 0  share of the blades that are reeds: straight, tall, a brown cattail near the tip
  oak: f32,           // @default 0  one old oak leaning in over one side: branches and a lobed, gappy canopy
  flowerVariety: f32, // @default 0  0 the scene's own flower colours, 1 a wildflower spread of every hue
  butterflies: f32,   // @default 0  butterflies fluttering across the sky by day
  fireflies: f32,     // @default 0  fireflies blinking among the plants at night
  bob: f32,           // @default 0  floating: the view rocks gently, as if drifting on water
  cave: f32,          // @default 0  a cavern ceiling of dark rock instead of open sky, with one opening far above
  glowworms: f32,     // @default 0  glowworm lights speckling the cavern ceiling
  caustics: f32,      // @default 0  underwater: the picture wavers and rippling light webs play over everything
  jellyfish: f32,     // @default 0  how many glowing jellyfish drift overhead
  fishes: f32,        // @default 0  how many glowing fish circle in small schools
  plankton: f32,      // @default 0  how many sparks of bioluminescent plankton drift about
  bioGlow: f32,       // @default 0  how strongly plants and flower heads glow from within
  bioColor: vec3f,    // @default [0.1, 0.9, 1.0]  the first bioluminescent colour
  bioColor2: vec3f,   // @default [0.9, 0.2, 1.0]  the second bioluminescent colour
  ambient: f32,       // @default 1  outside light reaching the scene — low down in a cave
  microbes: f32,      // @default 0  how many microorganisms float at different depths: cells, rods, diatoms
  dof: f32,           // @default 0  depth of field: how soft things get away from the focal plane — a macro lens, a microscope
  focus: f32,         // @default 1  the focal depth: 0.3 the far layers, 1 the middle, 1.5 right in front of the lens
  focusDrift: f32,    // @default 0  the focus racks slowly back and forth through the depths by this much
  bokeh: f32,         // @default 0  how many soft out-of-focus light discs float right before and far behind the lens
  translucency: f32,  // @default 0  how see-through plants and creatures are: 0 solid, 1 glassy, their glow kept
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

const TAU: f32 = 6.2831853;

// The light falling on the plants this frame: white at noon, warm at dusk, moonlit blue at night.
var<private> gLight: vec3f;
// The colour of the air: what far plants fade into.
var<private> gHaze: vec3f;
// Where the lens is focused this frame.
var<private> gFocus: f32;

// How soft something at this depth is, in view units: zero on the focal plane.
fn blurAt(depth: f32) -> f32 {
  return params.dof * 0.045 * abs(depth - gFocus);
}

fn pcg(v: u32) -> u32 {
  let s = v * 747796405u + 2891336453u;
  let w = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u;
  return (w >> 22u) ^ w;
}

// Lattice hash for value noise.
fn h2(p: vec2f) -> f32 {
  let q = vec2i(floor(p));
  return f32(pcg((bitcast<u32>(q.x) * 1597334677u) ^ pcg(bitcast<u32>(q.y)))) / 4294967295.0;
}

// The k-th random number of plant i, re-rolled by the seed.
fn rnd(i: u32, k: u32) -> f32 {
  let s = u32(max(params.seed, 0.0));
  return f32(pcg((i * 92837111u) ^ pcg(k * 689287499u + s * 3812015801u))) / 4294967295.0;
}

fn vnoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(h2(i), h2(i + vec2f(1.0, 0.0)), u.x),
             mix(h2(i + vec2f(0.0, 1.0)), h2(i + vec2f(1.0, 1.0)), u.x), u.y);
}

fn fbm(p: vec2f) -> f32 {
  var a = 0.5;
  var s = 0.0;
  var q = p;
  for (var i = 0; i < 5; i++) {
    s += a * vnoise(q);
    q = q * 2.03 + vec2f(17.1, 9.2);
    a *= 0.5;
  }
  return s;
}

// Streaky pastel strokes running along angle `ang`: long along, thin across. 0..1.
fn hatch(p: vec2f, ang: f32, boilT: f32) -> f32 {
  let c = cos(ang);
  let s = sin(ang);
  let q = vec2f(c * p.x + s * p.y, -s * p.x + c * p.y);
  let sc = max(params.stroke, 0.05);
  let k = vec2f(q.x * 10.0, q.y * 150.0) / sc + vec2f(boilT * 13.7, boilT * 7.3);
  let v = 0.65 * vnoise(k) + 0.35 * vnoise(k * vec2f(1.9, 0.55) + 31.0);
  return mix(0.5, clamp(v, 0.0, 1.0), clamp(params.amount, 0.0, 1.0));
}

// Rotate a colour's hue about the grey axis by angle a (radians).
fn hueShift(c: vec3f, a: f32) -> vec3f {
  let k = vec3f(0.57735027);
  let ca = cos(a);
  return c * ca + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - ca);
}

fn wrapAngle(d: f32) -> f32 {
  return d - TAU * round(d / TAU);
}

// The view: frame half-size, the look point the plants lean toward, the spin angle.
struct View {
  halfSize: vec2f,
  look: vec2f,
  cs: vec2f, // cos, sin of the spin — shared by every depth
  zoom: f32,
};

// Distance from the look point to the frame edge along unit direction d (d in spun space).
fn edgeDist(dSpun: vec2f, v: View) -> f32 {
  let d = vec2f(v.cs.x * dSpun.x + v.cs.y * dSpun.y, -v.cs.y * dSpun.x + v.cs.x * dSpun.y);
  let ex = select(v.halfSize.x + v.look.x, v.halfSize.x - v.look.x, d.x > 0.0);
  let ey = select(v.halfSize.y + v.look.y, v.halfSize.y - v.look.y, d.y > 0.0);
  return min(ex / max(abs(d.x), 1e-4), ey / max(abs(d.y), 1e-4));
}

// The view as seen from depth k: near things (k > 1) shift more than far ones (k < 1).
fn layerView(base: View, k: f32) -> View {
  let kk = mix(1.0, k, clamp(params.parallax, 0.0, 2.0));
  var v = base;
  v.look = base.look * kk;
  // A dolly: the nearer the layer, the more it grows.
  v.zoom = pow(base.zoom, kk);
  return v;
}

// A frame point in the spun, look-centred space of view v.
fn toView(p0: vec2f, v: View) -> vec2f {
  let q = (p0 - v.look) / v.zoom;
  return vec2f(v.cs.x * q.x - v.cs.y * q.y, v.cs.y * q.x + v.cs.x * q.y);
}

struct Blade {
  theta: f32,
  tip: f32,
  bend: f32,
  width: f32,
  phase: f32,
  root: f32,
};

// Centre-line angle of a blade at radius r: base angle, curve toward the tip, wind sway.
fn bladeAngle(b: Blade, r: f32, t: f32) -> f32 {
  let fromRoot = clamp((b.root - r) / b.root, 0.0, 1.0);
  let sway = params.wind * params.windGain * 0.18 * sin(t * (0.5 + 0.6 * b.phase) + b.theta * 5.0 + b.phase * TAU)
           * fromRoot * fromRoot;
  // A gust: a wave of wind travelling round the frame, leaning every plant it passes the same way.
  let gustW = params.gust * smoothstep(0.35, 0.9, vnoise(vec2f(b.theta * 1.2 - t * 0.9, t * 0.15)));
  return b.theta + b.bend * fromRoot * fromRoot + sway + 0.5 * gustW * fromRoot * fromRoot;
}

// A plant's life: x how grown it is (0..1), y which generation it is (a new plant each time round).
fn life(n: u32, t: f32) -> vec2f {
  let stagger = rnd(n, 13u);
  let grown = smoothstep(stagger * 0.6, stagger * 0.6 + 0.4, clamp(params.grow, 0.0, 1.0));
  if (params.lifespan <= 0.0) { return vec2f(grown, 0.0); }
  let ph = t / params.lifespan + rnd(n, 14u);
  let f = fract(ph);
  return vec2f(grown * smoothstep(0.0, 0.3, f) * (1.0 - smoothstep(0.8, 1.0, f)), floor(ph));
}

fn grassLayer(colIn: vec3f, p0: vec2f, base: View, kNear: f32, kFar: f32, i0: u32, i1: u32, t: f32, boilT: f32) -> vec3f {
  var col = colIn;
  let reach = clamp(params.reach, 0.0, 1.0);
  // The pixel's angle at depth 1: a blade whose whole sweep (bend, sway, parallax) cannot
  // reach it is skipped before any of its geometry is built.
  let pb = toView(p0, base);
  let a0 = atan2(pb.y, pb.x);
  // Parallax only bends a blade's angle as far as the look point actually moves it: nothing
  // when the view is centred, more the further it looks off and the nearer the pixel to the middle.
  let rpx = max(length(pb), 0.12);
  let slack = 0.2 * params.wind * params.windGain + 0.5 * params.gust + 0.1
            + 0.7 * clamp(params.parallax, 0.0, 2.0) * length(base.look) / rpx
            + 0.1 * max(params.leafWidth, 0.0) * (1.0 + 4.5 * clamp(params.fringe, 0.0, 1.0)) / max(rpx * base.zoom, 0.15)
            + params.dof * 0.07 / rpx;
  // Fixed slots: a plant count changes which slots are FILLED, never which plant sits where, so
  // a morph to a sparser scene shrinks plants back into the edge instead of reshuffling them.
  let density = clamp(params.grass / 240.0, 0.0, 1.0);
  // Past 1, Grow overgrows: taller, broader, beyond the scene's own reach.
  let over = max(params.grow - 1.0, 0.0);
  for (var n = i0; n < i1; n++) {
    // An empty slot costs one hash and nothing else.
    let filled = smoothstep(0.0, 0.05, density - rnd(n, 15u));
    if (filled <= 0.0) { continue; }
    var lf = life(n, t);
    lf.x *= filled;
    if (lf.x <= 0.01) { continue; }
    // A new generation is a different plant: same slot, fresh randoms.
    let i = n + u32(lf.y) * 7919u;
    let theta = TAU * rnd(i, 1u);
    // A reed stands nearly straight.
    let reed = rnd(i, 16u) < params.reeds;
    let bend = (rnd(i, 3u) - 0.5) * 2.4 * max(params.leafBend, 0.0) * select(1.0, 0.15, reed);
    if (abs(wrapAngle(a0 - theta)) > abs(bend) + slack) { continue; }
    // Each blade stands at its own depth, so each moves at its own speed.
    let depth = mix(kFar, kNear, rnd(i, 8u));
    let view = layerView(base, depth);
    let p = toView(p0, view);
    let r = length(p);
    var b: Blade;
    b.theta = theta;
    b.root = edgeDist(vec2f(cos(b.theta), sin(b.theta)), view) + 0.06;
    // Growing: the tip starts at the root and reaches out to where the plant ends up.
    let reedReach = select(1.0, 1.1, reed);
    b.tip = max(b.root - b.root * min(reach * reedReach, 0.95) * (0.2 + 0.8 * rnd(i, 2u)) * lf.x * (1.0 + 0.7 * over), 0.03);
    if (r < b.tip || r > b.root + 0.4) { continue; }
    let a = atan2(p.y, p.x);
    b.bend = bend;
    // Far plants are thinner; young ones too.
    b.width = (0.01 + 0.05 * rnd(i, 4u) * rnd(i, 4u)) * max(params.leafWidth, 0.0)
            * (0.5 + 0.45 * depth) * mix(0.35, 1.0, lf.x) * (1.0 + 0.5 * over) * select(1.0, 0.75, reed);
    b.phase = rnd(i, 6u);
    let phi = bladeAngle(b, r, t);
    let along = clamp((r - b.tip) / (b.root - b.tip), 0.0, 1.0);
    // A blade tapers to its tip; a broad leaf swells in the middle and narrows at both ends.
    let shape = clamp(params.leafShape, 0.0, 1.0);
    let leafProfile = 1.5 * pow(sin(3.14159 * clamp(along * 0.85 + 0.08, 0.0, 1.0)), 0.8);
    // A reed's cattail: a fat brown sausage a little below the tip.
    let cattail = select(0.0, smoothstep(0.04, 0.06, along) * smoothstep(0.17, 0.14, along), reed && lf.x > 0.7);
    let hw = max(b.width * mix(pow(along, 0.55), leafProfile, shape), b.width * 1.5 * cattail);
    let side = wrapAngle(a - phi) * r;
    let tex = hatch(p, phi, boilT);
    // Conifer: rounded tiers of foliage round the trunk, widest toward the root, a cone to the tip.
    let fr = clamp(params.fringe, 0.0, 1.0);
    let tierF = fract(r * 9.0 / view.zoom + rnd(i, 11u) * 7.0);
    // Each tier swells fast from the trunk and rounds off: a clump, with a clear notch before the next.
    let tier = pow(sin(3.14159 * pow(tierF, 0.7)), 0.6);
    let dist = abs(side) + (tex - 0.5) * (0.008 + 0.03 * fr);
    let hwF = hw * (1.0 + fr * (0.4 + 4.0 * tier) * smoothstep(0.0, 0.25, along) * (0.3 + 0.7 * along));
    // Out of focus, a leaf spreads into a soft, fainter band.
    let bl = blurAt(depth);
    let m = smoothstep(hwF + bl, hwF * 0.55 - bl * 0.5, dist) * (hwF / (hwF + bl * 0.6));
    if (m <= 0.0) { continue; }
    // Tone: near-black silhouettes, mid greens, sunlit yellow-greens.
    let tone = rnd(i, 5u);
    let ld = params.leafDarkColor;
    let lc = params.leafColor;
    var dark = ld;
    var lite = mix(ld, lc, 0.35);
    if (tone > 0.5) { dark = mix(ld, lc, 0.12); lite = lc; }
    if (tone > 0.86) { dark = mix(ld, lc, 0.6); lite = params.leafLightColor; }
    // A fold down the blade: one half catches the light.
    let lit = smoothstep(-hw, hw, side * sign(b.bend + 0.001));
    var c = mix(dark, lite, clamp(tex * (0.45 + 0.8 * lit), 0.0, 1.0));
    // Leaf light: the sky shines through the middle, the edges roll away darker, the tip
    // (toward the sky) is lit while the root (nearest the eye) sits in shade.
    let across = clamp(abs(side) / max(hw, 1e-4), 0.0, 1.0);
    c *= mix(0.68, 1.12, smoothstep(1.0, 0.25, across));
    c *= 0.72 + 0.5 * (1.0 - along);
    // A broad leaf's midrib and the veins running out from it toward the tip.
    c *= 1.0 - 0.45 * shape * smoothstep(hw * 0.12, 0.0, abs(side));
    let vein = smoothstep(0.1, 0.0, abs(fract(r * 26.0 + across * 1.6 + rnd(i, 12u)) - 0.5) - 0.38);
    c *= 1.0 - 0.22 * shape * vein * smoothstep(0.15, 0.35, across);
    c = mix(c, vec3f(0.11, 0.05, 0.015) * (0.55 + 0.8 * tex), cattail);
    // Each tier is lit on its sky side and shadowed underneath; bark shows down the middle.
    c *= mix(1.0, 0.4 + 1.0 * (1.0 - tierF), fr);
    c = mix(c, params.trunkColor * (0.6 + 0.7 * tex), fr * 0.7 * smoothstep(hw * 0.75, hw * 0.3, abs(side)));
    // Aerial perspective: the farther the plant, the more it fades into the air.
    let haze = clamp((1.0 - depth) * params.depthHaze * 0.9, 0.0, 0.45);
    // Bioluminescence: tips and edges glow from within, whatever the light.
    let bio = mix(params.bioColor, params.bioColor2, step(0.6, rnd(i, 19u)))
            * params.bioGlow * (0.8 * pow(1.0 - along, 2.0) + 0.45 * smoothstep(0.55, 1.0, across)) * (0.6 + 0.6 * tex);
    // Translucent: the layers behind show through the body; the glow stays whole.
    let tr = clamp(params.translucency, 0.0, 1.0);
    col = mix(col, mix(c * gLight, gHaze, haze), m * (1.0 - 0.6 * tr)) + bio * m;
  }
  return col;
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let res = frameU.resolution;
  let aspect = res.x / max(res.y, 1.0);
  // Stop motion: the scene is posed fps times a second and held in between.
  let t = select(frameU.absTime, floor(frameU.absTime * params.fps) / max(params.fps, 1e-3), params.fps > 0.0);
  let boilT = select(0.0, floor(frameU.absTime * params.boil), params.boil > 0.0);
  // The far sky is redrawn slower, with broader strokes: nothing scratches in the distance.
  let boilFar = select(0.0, floor(frameU.absTime * params.boil * 0.3), params.boil > 0.0);

  // ── Day and night. h is the sun's height: 1 at noon, -1 at midnight, 0 at dawn and dusk.
  let cyc = select(0.0, frameU.absTime / max(params.dayLength, 1e-3), params.dayLength > 0.0);
  let tod = fract(params.timeOfDay + cyc);
  let h = sin(TAU * (tod - 0.25));
  let dayK = clamp(params.dayAmount, 0.0, 1.0);
  let day = mix(1.0, smoothstep(-0.1, 0.45, h), dayK);
  let dusk = dayK * exp(-(h * h) / 0.04);
  let night = 1.0 - day;
  gLight = mix(vec3f(0.05, 0.07, 0.16), vec3f(1.0), day) * (1.0 + dusk * vec3f(0.5, 0.05, -0.35)) * max(params.ambient, 0.0);
  // At dusk the blue drains out first, then the warm comes in low.
  let skyC = mix(vec3f(0.003, 0.006, 0.025), params.skyColor, day) * (1.0 - dusk * vec3f(0.0, 0.35, 0.7))
           + dusk * vec3f(0.3, 0.06, 0.02);
  let hazeC = mix(vec3f(0.01, 0.018, 0.05), params.hazeColor, day) * (1.0 - dusk * vec3f(0.0, 0.3, 0.75))
            + dusk * vec3f(0.8, 0.3, 0.04);

  // The base view at depth 1. Pad Y up is screen up; uv runs down. The view also wanders on its own.
  var base: View;
  base.halfSize = vec2f(0.5 * aspect, 0.5);
  let tw = t * params.wanderSpeed;
  let wand = params.wander * vec2f(sin(tw * 0.23 + 0.7) + 0.4 * sin(tw * 0.61), sin(tw * 0.17 + 2.1) + 0.4 * sin(tw * 0.53));
  // Floating: a slow rock on the water.
  let bobV = params.bob * vec2f(sin(t * 0.41) + 0.3 * sin(t * 1.07), sin(t * 0.33 + 1.3) + 0.3 * sin(t * 0.93));
  let lk = clamp(vec2f(params.lookX, params.lookY) + wand + 0.18 * bobV, vec2f(-1.0), vec2f(1.0));
  base.look = vec2f(lk.x * 0.3 * aspect, -lk.y * 0.3);
  let ang = params.spin * t + params.roll + params.bob * 0.06 * sin(t * 0.27 + 0.5);
  base.cs = vec2f(cos(ang), sin(ang));
  base.zoom = clamp(params.zoom, 0.5, 4.0) * (1.0 + params.zoomPulse * sin(t * params.zoomSpeed))
            * (1.0 + params.bob * 0.025 * sin(t * 0.52));
  gHaze = mix(hazeC, skyC, 0.3);
  gFocus = params.focus + params.focusDrift * 0.5 * sin(t * 0.21);
  var p0 = (uv - 0.5) * vec2f(aspect, 1.0);
  // Underwater, everything wavers.
  p0 += params.caustics * 0.007 * vec2f(sin(p0.y * 19.0 + t * 1.3), cos(p0.x * 17.0 + t * 1.1));
  let rootR = 0.5 * length(vec2f(aspect, 1.0)) + 0.04;

  // Far layers: the sky barely moves, the clouds a little more.
  let skyView = layerView(base, 0.1);
  let p = toView(p0, skyView);
  let r = length(p);

  // ── Sky: deep blue at the rim, lighter toward the centre, scratched with pale strokes.
  let skyAng = 1.25;
  let skyTex = hatch(p * 0.5, skyAng, boilFar);
  var col = mix(hazeC, skyC, smoothstep(0.1, rootR, r));
  col *= 0.88 + 0.24 * skyTex;
  let speck = smoothstep(0.8, 0.95, hatch(p * 0.4 + 7.0, skyAng + 0.15, boilFar + 3.0));
  col = mix(col, mix(hazeC, vec3f(1.0), 0.3 * day), speck * 0.18 * clamp(params.amount, 0.0, 1.0));

  // Stars, only at night, twinkling as the drawing boils.
  let sq = p * 38.0;
  let sh = h2(floor(sq) + 91.0);
  let sj = vec2f(h2(floor(sq) + 17.0), h2(floor(sq) + 53.0)) - 0.5;
  let star = select(0.0, smoothstep(0.09, 0.0, length(fract(sq) - 0.5 - sj * 0.6)), sh > 0.982);
  col += vec3f(0.8, 0.85, 1.0) * star * night * (0.6 + 0.4 * h2(floor(sq) + boilFar));

  // The sun travels round the sky; it glows through the scene's own haze and burns orange at dusk.
  let sunP = vec2f(0.3 * aspect * sin(TAU * tod), -0.26 * cos(TAU * tod));
  let sunVis = smoothstep(-0.2, 0.05, h);
  let sunGlow = exp(-length(p - sunP) * 3.0) * sunVis;
  let glowC = mix(params.glowColor, vec3f(1.0, 0.36, 0.08), clamp(dusk, 0.0, 1.0));
  col = mix(col, glowC, clamp((params.glow + 0.9 * dusk) * sunGlow, 0.0, 1.0));
  // The moon, opposite the sun.
  let moonD = length(p + sunP);
  let moonVis = smoothstep(0.05, -0.2, h) * dayK;
  col = mix(col, vec3f(0.85, 0.85, 0.72), moonVis * (smoothstep(0.034, 0.028, moonD) + 0.25 * exp(-moonD * 9.0)));

  // ── Clouds: chalky cream blobs drifting across the open sky.
  let drift = vec2f(t * 0.012, t * 0.004);
  let pc = toView(p0, layerView(base, 0.25));
  let cl = fbm(pc * 4.2 + drift + vec2f(params.seed * 3.1, 0.0));
  let th = 0.86 - clamp(params.clouds, 0.0, 1.0) * 0.36;
  let cloudTex = hatch(pc * 0.6, 0.9, boilFar + 5.0);
  let cm = smoothstep(th, th + 0.05, cl + (cloudTex - 0.5) * 0.12) * smoothstep(rootR * 0.85, rootR * 0.3, r);
  let cloudLit = params.cloudColor * mix(vec3f(0.12, 0.13, 0.2), vec3f(1.0), day) + dusk * vec3f(0.55, 0.22, 0.18);
  let cloudCol = mix(mix(skyC, cloudLit, 0.55), cloudLit, clamp(cloudTex * 1.2 + (cl - th) * 3.0, 0.0, 1.0));
  col = mix(col, cloudCol, cm);

  // ── The cavern: dark rock overhead, cracked, glowworms in it, one opening far above.
  if (params.cave > 0.01) {
    let pcv = toView(p0, layerView(base, 0.2));
    let rk = fbm(pcv * 3.5 + 11.0);
    let rk2 = fbm(pcv * 12.0 + 5.0);
    var rock = mix(vec3f(0.006, 0.01, 0.02), vec3f(0.035, 0.045, 0.065), rk) * (0.6 + 0.8 * rk2);
    rock *= 1.0 - 0.7 * smoothstep(0.025, 0.0, abs(rk - 0.5));
    rock *= max(params.ambient, 0.05) * 2.5;
    let hole = smoothstep(0.2, 0.1, length(pcv - vec2f(0.06, -0.04)) + (rk - 0.5) * 0.18);
    let gq = pcv * 42.0;
    let gh = h2(floor(gq) + 77.0);
    let gj = vec2f(h2(floor(gq) + 3.0), h2(floor(gq) + 9.0)) - 0.5;
    let gw = select(0.0, smoothstep(0.14, 0.0, length(fract(gq) - 0.5 - gj * 0.6)), gh > 1.0 - 0.07 * params.glowworms);
    rock += mix(params.bioColor, vec3f(0.3, 0.6, 1.0), 0.5) * gw * (0.7 + 0.3 * sin(t * 1.3 + gh * 40.0)) * 1.4;
    col = mix(col, mix(rock, col, hole), clamp(params.cave, 0.0, 1.0));
  }

  // ── Foliage mass: a ragged dark ring of leaves hugging the frame edge — the nearest thing.
  let rimView = layerView(base, 1.35);
  let pr = toView(p0, rimView);
  let rr = length(pr);
  let ar = atan2(pr.y, pr.x);
  let dir = pr / max(rr, 1e-5);
  let rimN = fbm(dir * 2.5 + vec2f(params.seed * 7.3, 1.0));
  let rimR = edgeDist(dir, rimView) * (1.0 - clamp(params.reach, 0.0, 1.0) * (0.05 + 0.6 * rimN * rimN));
  let rimTex = hatch(pr, ar, boilT + 2.0);
  let rimM = smoothstep(rimR, rimR + 0.03, rr + (rimTex - 0.5) * 0.04);
  col = mix(col, mix(params.leafDarkColor * 0.7, mix(params.leafDarkColor, params.leafColor, 0.4), rimTex * rimTex) * gLight, rimM);

  // ── Plants in three depth bands, far to near, each moving at its own speed.
  col = grassLayer(col, p0, base, 0.55, 0.3, 0u, 96u, t, boilT);

  // ── The oak: one old tree leaning in over one side of the sky.
  if (params.oak > 0.01) {
    let oakView = layerView(base, 0.75);
    let po = toView(p0, oakView);
    let oa = 2.2 + params.seed * 1.7;
    let u = vec2f(cos(oa), sin(oa));
    let edgeO = edgeDist(u, oakView);
    let s = dot(po, u) / max(edgeO, 1e-3); // 1 at the frame edge the oak stands on, 0 at the centre
    let along = dot(po, vec2f(-u.y, u.x));
    let sway = params.wind * params.windGain * 0.01 * sin(t * 0.7);
    let lobes = fbm(po * 3.0 + vec2f(params.seed, 2.0));
    let reachO = 0.78 * clamp(params.oak, 0.0, 1.0) * clamp(params.grow, 0.0, 1.5);
    let canopy = smoothstep(1.0 - reachO + 0.08, 1.0 - reachO - 0.02, 1.0 - s - (lobes - 0.5) * 0.5 - 0.15 * cos(along * 2.2));
    // Branches: dark limbs fanning from the trunk at the edge into the canopy.
    var branch = 0.0;
    for (var k = 0u; k < 6u; k++) {
      let ba = (f32(k) - 2.5) * 0.32 + (rnd(4000u + k, 1u) - 0.5) * 0.2;
      let bd = -vec2f(cos(oa + ba), sin(oa + ba));
      let o = u * edgeO * 1.05;
      let q = po - o;
      let tq = clamp(dot(q, bd), 0.0, edgeO * reachO * 1.4);
      let dq = length(q - bd * tq + vec2f(-bd.y, bd.x) * sin(tq * 9.0 + f32(k)) * 0.015);
      let wq = 0.022 * (1.0 - tq / max(edgeO * reachO * 1.4, 1e-3)) + 0.003;
      branch = max(branch, smoothstep(wq, wq * 0.6, dq));
    }
    let oakTex = hatch(po, oa + 1.57, boilT + 4.0);
    col = mix(col, params.trunkColor * (0.5 + 0.8 * oakTex) * gLight, branch);
    // Leaf clumps with sky between them, lit on the sky side.
    let clump = fbm(po * 11.0 + vec2f(sway * 30.0, 7.0) + params.seed);
    let leafM = canopy * smoothstep(0.38, 0.46, clump + (oakTex - 0.5) * 0.12);
    let litO = smoothstep(0.4, 0.75, clump) * (0.5 + 0.5 * (1.0 - s));
    let oakC = mix(params.leafDarkColor, mix(params.leafColor, params.leafLightColor, litO), 0.25 + 0.75 * litO) * (0.7 + 0.5 * oakTex);
    col = mix(col, oakC * gLight, leafM);
  }

  // ── Butterflies, by day: wings opening and closing as they wander the open sky.
  let nB = u32(clamp(params.butterflies, 0.0, 16.0));
  for (var k = 0u; k < nB; k++) {
    let bv = layerView(base, 0.8);
    let pbf = toView(p0, bv);
    let r1 = rnd(5000u + k, 1u);
    let r2 = rnd(5000u + k, 2u);
    let r3 = rnd(5000u + k, 3u);
    let bc = vec2f(sin(t * 0.17 * (1.0 + r1) + r2 * TAU) * 0.42 * aspect, cos(t * 0.13 * (1.0 + r2) + r3 * TAU) * 0.33)
           + 0.03 * vec2f(sin(t * 2.3 + r1 * 9.0), cos(t * 1.9 + r2 * 9.0));
    let size = 0.02 * (0.8 + 0.5 * r3);
    let d = pbf - bc;
    if (dot(d, d) > size * size * 6.0) { continue; }
    let hd = r1 * TAU + 0.8 * sin(t * 0.5 + r2 * 6.0);
    let l = vec2f(cos(hd) * d.x + sin(hd) * d.y, -sin(hd) * d.x + cos(hd) * d.y);
    let flap = 0.25 + 0.75 * abs(sin(t * 9.0 + r3 * 6.0));
    let wx = abs(l.x) / max(flap, 0.05);
    let upper = length(vec2f(wx - size * 0.6, l.y - size * 0.25) / vec2f(size * 0.6, size * 0.5));
    let lower = length(vec2f(wx - size * 0.45, l.y + size * 0.4) / vec2f(size * 0.42, size * 0.38));
    let wing = smoothstep(1.05, 0.9, min(upper, lower));
    let body = smoothstep(size * 0.12, size * 0.06, abs(l.x)) * smoothstep(size * 0.7, size * 0.5, abs(l.y));
    var wc = vec3f(1.0, 0.42, 0.04);
    if (r2 > 0.6) { wc = vec3f(0.95, 0.95, 0.85); }
    if (r2 > 0.85) { wc = vec3f(0.15, 0.35, 0.95); }
    wc = mix(wc * 0.25, wc, smoothstep(1.0, 0.75, min(upper, lower)));
    col = mix(col, wc * gLight, wing * day);
    col = mix(col, vec3f(0.02) * gLight, body * day);
  }
  // ── Jellyfish: glowing bells drifting overhead, seen from below — rim, four lobes, waving tentacles.
  let nJ = u32(clamp(params.jellyfish, 0.0, 12.0));
  for (var k = 0u; k < nJ; k++) {
    let j1 = rnd(7000u + k, 1u);
    let j2 = rnd(7000u + k, 2u);
    let j3 = rnd(7000u + k, 3u);
    let pj = toView(p0, layerView(base, 0.55 + 0.6 * j3));
    let jc = vec2f(sin(t * 0.05 * (1.0 + j1) + j2 * TAU) * 0.4 * aspect, cos(t * 0.04 * (1.0 + j2) + j1 * TAU) * 0.3);
    let js = 0.045 * (0.6 + 0.8 * j3) * (0.88 + 0.12 * sin(t * 2.0 + j1 * 6.0));
    let jb = blurAt(0.55 + 0.6 * j3) / js;
    let jFade = 1.0 / (1.0 + jb * 2.0);
    let d = pj - jc;
    let dl = length(d) / js;
    if (dl > 1.9 + jb) { continue; }
    let ja = atan2(d.y, d.x) + t * 0.1;
    let jcol = mix(params.bioColor, params.bioColor2, j2);
    let bell = smoothstep(1.0 + jb, 0.9 - jb, dl);
    let rim = smoothstep(0.65 - jb, 1.0, dl) * bell;
    let lobe = pow(abs(cos(2.0 * ja)), 3.0) * smoothstep(0.55, 0.15, dl);
    let tent = smoothstep(0.08, 0.0, abs(fract(ja * 1.273 + sin(dl * 6.0 - t * 2.0) * 0.08) - 0.5) - 0.4)
             * smoothstep(1.9, 1.0, dl) * step(1.0, dl);
    col = mix(col, col * 0.6 + jcol * 0.15, bell * mix(0.7, 0.3, clamp(params.translucency, 0.0, 1.0)) * jFade);
    col += jcol * (rim * 0.9 + lobe * 0.55 + tent * 0.35 * jFade) * jFade;
  }

  // ── Microorganisms at every depth, far ones first: cells, rods, diatoms, translucent and glowing.
  let nM = u32(clamp(params.microbes, 0.0, 24.0));
  for (var k = 0u; k < nM; k++) {
    let m1 = rnd(9500u + k, 1u);
    let m2 = rnd(9500u + k, 2u);
    let m3 = rnd(9500u + k, 3u);
    let m4 = rnd(9500u + k, 4u);
    let m5 = rnd(9500u + k, 5u);
    let mdepth = 0.3 + 1.3 * (f32(k) + m1) / f32(nM);
    let pm = toView(p0, layerView(base, mdepth));
    let mc = vec2f(sin(t * 0.03 * (1.0 + m2) + m3 * TAU) * 0.45 * aspect, cos(t * 0.025 * (1.0 + m3) + m2 * TAU) * 0.35);
    let ms = (0.025 + 0.035 * m4) * (0.5 + 0.7 * mdepth);
    let mb = blurAt(mdepth);
    let d = pm - mc;
    if (length(d) > ms * 1.8 + mb * 3.0) { continue; }
    let ro = m5 * TAU + t * 0.05 * (m1 - 0.5);
    let l = vec2f(cos(ro) * d.x + sin(ro) * d.y, -sin(ro) * d.x + cos(ro) * d.y);
    let kind = u32(m2 * 3.0);
    var q = l / ms;
    if (kind == 1u) { q = vec2f(max(abs(l.x) - ms * 0.9, 0.0), l.y) / (ms * 0.42); }
    let wob = select(0.0, 0.05 * sin(atan2(l.y, l.x) * 9.0 + t * 3.0 + m3 * 9.0), kind == 0u);
    let dn = length(q) + wob;
    let bN = mb / ms;
    let fade = 1.0 / (1.0 + bN * 2.5);
    let fill = smoothstep(1.0 + bN, 0.92 - bN, dn);
    let rim = fill * smoothstep(0.72 - bN, 1.0, dn);
    let nucleus = select(0.0, smoothstep(0.3 + bN, 0.2 - bN, length(q - vec2f(0.22, 0.08))), kind != 2u);
    let organ = fill * step(0.82, h2(floor(q * 5.0 + m4 * 10.0))) * (1.0 - bN) * 0.6;
    let rib = select(0.0, smoothstep(0.1, 0.0, abs(fract(atan2(q.y, q.x) * 1.91) - 0.5) - 0.38) * fill * (1.0 - smoothstep(0.0, 0.5, bN)), kind == 2u);
    let mcol = mix(params.bioColor, params.bioColor2, m3);
    col = mix(col, col * 0.7 + mcol * 0.1, fill * mix(0.6, 0.3, clamp(params.translucency, 0.0, 1.0)) * fade);
    col += mcol * (rim * 0.7 + nucleus * 0.35 + organ * 0.3 + rib * 0.45) * fade;
  }

  // ── Fish: small schools circling, dark bodies with a glowing stripe.
  let nFi = u32(clamp(params.fishes, 0.0, 24.0));
  let pfi = toView(p0, layerView(base, 0.8));
  for (var k = 0u; k < nFi; k++) {
    let school = k / 6u;
    let s1 = rnd(8000u + school, 1u);
    let s2 = rnd(8000u + school, 2u);
    let f1 = rnd(8100u + k, 1u);
    let f2 = rnd(8100u + k, 2u);
    let dirS = select(-1.0, 1.0, s2 > 0.5);
    let fa = t * 0.35 * dirS + s1 * TAU + f1 * 0.35;
    let frad = (0.18 + 0.2 * s2) * (1.0 + 0.12 * (f2 - 0.5));
    let fcen = vec2f(cos(fa) * frad * aspect * 0.8, sin(fa) * frad) + 0.03 * vec2f(f2 - 0.5, f1 - 0.5);
    let d = pfi - fcen;
    if (dot(d, d) > 0.0016) { continue; }
    let hd = fa + 1.5708 * dirS;
    let l = vec2f(cos(hd) * d.x + sin(hd) * d.y, -sin(hd) * d.x + cos(hd) * d.y);
    let fL = 0.016;
    let fW = 0.0055;
    let body = smoothstep(1.0, 0.85, length(l / vec2f(fL, fW)));
    let tx = -l.x - fL * 0.8;
    let tail = step(0.0, tx) * step(tx, fL * 0.7) * step(abs(l.y + 0.002 * sin(t * 8.0 + f1 * 9.0)), tx * 0.9);
    let fish = max(body, tail);
    let stripe = body * smoothstep(fW * 0.35, 0.0, abs(l.y));
    col = mix(col, vec3f(0.005, 0.01, 0.02), fish * 0.9);
    col += mix(params.bioColor, params.bioColor2, s1) * stripe * 0.9;
  }

  col = grassLayer(col, p0, base, 0.9, 0.6, 96u, 180u, t, boilT);

  // ── Flowers: thin stems, then fuzzy pom-pom heads at their tips.
  let reach = clamp(params.reach, 0.0, 1.0);
  let pfb = toView(p0, base);
  let fa0 = atan2(pfb.y, pfb.x);
  let fSlack = 0.75 + 0.2 * params.wind * params.windGain + 0.5 * params.gust
             + 0.7 * clamp(params.parallax, 0.0, 2.0) * length(base.look) / max(length(pfb), 0.12)
             + 0.25 * params.flowerSize * max(params.headStretch, 1.0) / max(length(pfb) * base.zoom, 0.12);
  for (var j = 0u; j < 40u; j++) {
    // The count fades the last flower in or out; the ones before it never move.
    let pres = clamp(params.flowers - f32(j), 0.0, 1.0);
    if (pres <= 0.0) { break; }
    // Skip a flower whose stem and head cannot swing as far as this pixel's angle.
    let thetaF = f32(j) * 2.39996323 + 0.35 * (rnd(1000u + j, 1u) - 0.5) + params.seed * 0.37;
    if (abs(wrapAngle(fa0 - thetaF)) > fSlack) { continue; }
    var lf = life(1000u + j, t);
    lf.x *= pres;
    if (lf.x <= 0.01) { continue; }
    let id = 1000u + j + u32(lf.y) * 7919u;
    // Bigger heads are nearer: they move faster.
    let near = rnd(id, 4u);
    let view = layerView(base, mix(0.65, 1.15, near));
    let p = toView(p0, view);
    let r = length(p);
    let a = atan2(p.y, p.x);
    var b: Blade;
    // The golden angle: any number of flowers spreads evenly round the frame, and adding one moves none.
    b.theta = thetaF;
    b.root = edgeDist(vec2f(cos(b.theta), sin(b.theta)), view) + 0.06;
    let overF = 1.0 + 0.7 * max(params.grow - 1.0, 0.0);
    b.tip = max(b.root - b.root * reach * (0.3 + 0.7 * rnd(id, 2u)) * lf.x * overF, 0.05);
    b.bend = (rnd(id, 3u) - 0.5) * 1.2;
    b.width = 0.004;
    b.phase = rnd(id, 6u);
    // Heads nearer the frame edge are nearer the eye, so bigger.
    // The head opens once the stem is up.
    let size = params.flowerSize * (0.035 + 0.065 * near) * (0.6 + 0.8 * b.tip / b.root) * smoothstep(0.55, 1.0, lf.x) * (0.6 + 0.4 * overF);

    if (r > b.tip && r < b.root + 0.4) {
      let phi = bladeAngle(b, r, t);
      let side = wrapAngle(a - phi) * r;
      let tex = hatch(p, phi, boilT);
      let m = smoothstep(b.width, b.width * 0.4, abs(side) + (tex - 0.5) * 0.003);
      col = mix(col, mix(mix(params.leafDarkColor, params.leafColor, 0.3), mix(params.leafColor, params.leafLightColor, 0.4), tex) * gLight, m);
    }

    let hp = bladeAngle(b, b.tip, t);
    let sdir = vec2f(cos(hp), sin(hp)); // along the stem, pointing back to its root
    let stretch = max(params.headStretch, 0.3);
    // A tassel hangs on past the stem tip, toward the middle of the sky.
    let hc = b.tip * sdir - sdir * size * (stretch - 1.0) * 0.8;
    let d = p - hc;
    let dl0 = length(d);
    if (dl0 < size * (1.8 + stretch)) {
      let pet = clamp(params.headPetals, 0.0, 1.0);
      // A sunflower is seen from below and to the side: each face foreshortened its own amount.
      let tilt = mix(1.0, 0.8 + 0.2 * rnd(id, 12u), pet);
      let dq = vec2f(dot(d, sdir) / (stretch * tilt), dot(d, vec2f(-sdir.y, sdir.x)));
      let dl = length(dq);
      let ah = atan2(dq.y, dq.x);
      // Pom-pom fuzz radiates; tassel strands run along the stem.
      let fuzz = hatch(p * 1.4, select(atan2(d.y, d.x), hp, stretch > 1.6), boilT + 11.0);
      let tongue = pow(abs(cos(ah * 8.0 + rnd(id, 9u) * 6.0)), 2.0);
      let edge = size * mix(0.75 + 0.5 * fuzz, 0.55 + 0.75 * tongue + 0.15 * fuzz, pet);
      let m = smoothstep(edge, edge * 0.9, dl);
      // Backlit: the rim facing the open sky glows, the core stays dark. A sunflower's petals all glow.
      let toSky = -normalize(hc + vec2f(1e-5, 0.0));
      let litSide = 0.5 + 0.5 * dot(d / max(dl0, 1e-5), toSky);
      let rimPom = smoothstep(0.5, 1.05, dl / size) * (0.2 + 0.8 * litSide);
      let rimSun = smoothstep(0.42, 0.56, dl / size) * (0.6 + 0.4 * litSide);
      let rim = mix(rimPom, rimSun, pet);
      var petal = params.petalColor;
      let kind = rnd(id, 7u);
      if (kind > 0.55) { petal = params.accentColor; }
      if (kind > 0.85) { petal = params.petalColor * 0.55; }
      // Wildflowers: most heads take a hue of their own; about a third stay the scene's colour.
      let hueR = rnd(id, 17u);
      let wild = 0.55 + 0.45 * cos(TAU * (hueR + vec3f(0.0, 0.33, 0.67)));
      let wildC = wild * wild * vec3f(1.0, 0.85, 1.0);
      petal = mix(petal, wildC, clamp(params.flowerVariety, 0.0, 1.0) * step(0.33, rnd(id, 18u)));
      var headCol = mix(params.heartColor, petal, clamp(rim * (0.4 + 1.1 * fuzz), 0.0, 1.0));
      // Seeds packed in the sunflower's disc.
      let seed = step(0.62, h2(dq * 34.0 / max(size, 1e-3) + f32(id)));
      headCol += pet * seed * smoothstep(0.5, 0.2, dl / size) * vec3f(0.12, 0.06, 0.01);
      let headBio = mix(params.bioColor, params.bioColor2, rnd(id, 19u)) * params.bioGlow * (0.35 + 0.9 * rim) * (0.6 + 0.6 * fuzz);
      col = mix(col, headCol * gLight, m * (1.0 - 0.5 * clamp(params.translucency, 0.0, 1.0))) + headBio * m;
    }
  }

  // ── Front grass, over the flowers.
  col = grassLayer(col, p0, base, 1.45, 1.0, 180u, 240u, t, boilT);

  // ── Fireflies, at night: slow drifting sparks among the plants, each blinking on its own beat.
  let nF = u32(clamp(params.fireflies, 0.0, 64.0));
  let ffVis = smoothstep(0.25, 0.75, night);
  if (ffVis > 0.0) {
    let fv = layerView(base, 1.0);
    let pf = toView(p0, fv);
    for (var k = 0u; k < nF; k++) {
      let f1 = rnd(6000u + k, 1u);
      let f2 = rnd(6000u + k, 2u);
      let f3 = rnd(6000u + k, 3u);
      let fa = f1 * TAU + 0.15 * sin(t * 0.2 + f2 * 6.0);
      let fdir = vec2f(cos(fa), sin(fa));
      let fc = fdir * edgeDist(fdir, fv) * (0.45 + 0.45 * f2) + 0.04 * vec2f(sin(t * 0.7 + f3 * 9.0), cos(t * 0.6 + f1 * 9.0));
      let fd = length(pf - fc);
      if (fd > 0.08) { continue; }
      let blink = smoothstep(0.55, 1.0, sin(t * (1.1 + f3) + f2 * TAU));
      let glowF = smoothstep(0.006, 0.0, fd) + 0.4 * exp(-fd * 70.0);
      col += vec3f(0.85, 1.0, 0.3) * blink * glowF * ffVis;
    }
  }

  // ── Bokeh: soft discs of light, way out of focus — some right before the lens, some far behind.
  let nBk = u32(clamp(params.bokeh, 0.0, 40.0));
  for (var k = 0u; k < nBk; k++) {
    let b1 = rnd(9800u + k, 1u);
    let b2 = rnd(9800u + k, 2u);
    let b3 = rnd(9800u + k, 3u);
    let near = b3 > 0.45;
    let bdepth = select(0.15 + 0.15 * b1, 1.7 + 0.5 * b1, near);
    let pk = toView(p0, layerView(base, bdepth));
    let bcn = (vec2f(b1, b2) - 0.5) * vec2f(aspect, 1.0) * 1.2
            + 0.06 * vec2f(sin(t * 0.07 + b3 * 9.0), cos(t * 0.06 + b1 * 9.0));
    let bR = select(0.025 + 0.04 * b2, 0.06 + 0.08 * b2, near) * (0.6 + 0.4 * params.dof);
    let bd = pk - bcn;
    let bl = length(bd);
    if (bl > bR * 1.1) { continue; }
    // A six-bladed aperture: the disc is a soft hexagon with a brighter rim.
    let hexD = bl * (1.0 + 0.045 * cos(6.0 * atan2(bd.y, bd.x)));
    let disc = smoothstep(bR, bR * 0.9, hexD);
    let ring = smoothstep(bR * 0.72, bR * 0.96, hexD) * disc;
    let bcol = mix(params.bioColor, params.bioColor2, step(0.6, b2)) * mix(vec3f(1.0), vec3f(1.0, 0.9, 0.8), b1);
    let bI = select(0.1, 0.07, near) * (0.75 + 0.25 * sin(t * 0.3 + b2 * 9.0));
    col += bcol * (disc * bI + ring * bI * 0.9);
  }

  // ── Plankton: sparks drifting everywhere, blinking softly.
  let nP = u32(clamp(params.plankton, 0.0, 80.0));
  if (nP > 0u) {
    let pp = toView(p0, layerView(base, 0.9));
    for (var k = 0u; k < nP; k++) {
      let q1 = rnd(9000u + k, 1u);
      let q2 = rnd(9000u + k, 2u);
      let q3 = rnd(9000u + k, 3u);
      let pc2 = (vec2f(q1, q2) - 0.5) * vec2f(aspect, 1.0) * 1.1 + 0.05 * vec2f(sin(t * 0.3 + q3 * 9.0), cos(t * 0.25 + q1 * 9.0));
      let pd = length(pp - pc2);
      // Out of focus, a spark opens into a soft, dim disc.
      let pr0 = 0.004 + blurAt(0.3 + 1.2 * q1);
      if (pd > pr0 * 2.5 + 0.02) { continue; }
      let blink = 0.55 + 0.45 * sin(t * (0.4 + 0.5 * q3) + q2 * TAU);
      let pAmt = (0.004 / pr0) * (0.004 / pr0);
      col += mix(params.bioColor, params.bioColor2, step(0.75, q3)) * blink
           * (smoothstep(pr0, pr0 * 0.6, pd) * max(pAmt, 0.12) + 0.2 * exp(-pd * 90.0) * pAmt);
    }
  }

  // ── Caustics: the water surface focusing light into a rippling web.
  if (params.caustics > 0.01) {
    let cq = p0 * 7.0;
    let n1 = vnoise(cq + vec2f(t * 0.3, t * 0.2));
    let n2 = vnoise(cq * 1.3 - vec2f(t * 0.25, -t * 0.15) + 4.0);
    let cau = pow(clamp(1.0 - abs(n1 - n2) * 4.0, 0.0, 1.0), 4.0);
    col += mix(vec3f(0.35, 0.75, 1.0), params.bioColor, 0.4) * cau * params.caustics * 0.3;
  }

  return vec4f(col, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  amount: f32,   // @default 1  strength of the whole hand-drawn finish — 0 passes the picture through
  wobble: f32,   // @default 1.5  pixels the outlines shiver each time the drawing boils
  boil: f32,     // @default 8  times a second the outlines shiver — match the meadow's boil
  grain: f32,    // @default 0.12  paper tooth showing through the pastel
  vignette: f32, // @default 0.25  darkening toward the frame corners
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

fn pcg(v: u32) -> u32 {
  let s = v * 747796405u + 2891336453u;
  let w = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u;
  return (w >> 22u) ^ w;
}

fn h2(p: vec2f) -> f32 {
  let q = vec2i(floor(p));
  return f32(pcg((bitcast<u32>(q.x) * 1597334677u) ^ pcg(bitcast<u32>(q.y)))) / 4294967295.0;
}

fn vnoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(h2(i), h2(i + vec2f(1.0, 0.0)), u.x),
             mix(h2(i + vec2f(0.0, 1.0)), h2(i + vec2f(1.0, 1.0)), u.x), u.y);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let res = max(frameU.resolution, vec2f(1.0));
  let amt = clamp(params.amount, 0.0, 1.0);
  let boilT = select(0.0, floor(frameU.absTime * params.boil), params.boil > 0.0);
  let px = uv * res;

  // Boil: the whole drawing is re-traced a few times a second, so every edge shivers.
  let w = vec2f(vnoise(px / 24.0 + boilT * 17.0), vnoise(px / 24.0 + boilT * 17.0 + 53.0)) - 0.5;
  let suv = uv + w * 2.0 * params.wobble * amt / res;
  var col = textureSampleLevel(inputTexture, inputSampler, suv, 0.0).rgb;

  // Paper tooth: fine grain that lifts the pastel off the darks.
  // Paper tooth is the paper's, so it holds still while the drawing boils over it.
  let g = vnoise(px / 1.6) * 0.6 + vnoise(px / 5.0) * 0.4;
  col += (g - 0.5) * params.grain * amt * (0.25 + col);

  let v = length(uv - 0.5) * 1.41;
  col *= 1.0 - params.vignette * amt * v * v;
  return vec4f(max(col, vec3f(0.0)), 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  amount: f32,       // @default 1  how much of the picture is re-painted in strokes — 0 passes it through
  size: f32,         // @default 1  scale of every stroke
  fps: f32,          // @default 8  stop-motion rate: every stroke is re-laid this many times a second and held in between
  jitter: f32,       // @default 1  how far each re-lay moves a stroke — the frame-to-frame delta
  shake: f32,        // @default 3  pixels the whole drawing slips each re-lay, like a sheet nudged on a light box
  flowAngle: f32,    // @default 1.2  stroke direction where the picture has no edge to follow, radians
  detail: f32,       // @default 0.4  how readily the fine strokes gather on edges and detail, 0 to 1
  colorJitter: f32,  // @default 0.04  per-stroke drift in value and hue, like grabbing the neighbouring crayon
  dryness: f32,      // @default 0.3  gaps in each stroke where the pastel skipped over the paper tooth
  hold: f32,         // @default 3  stop-motion frames each stroke lives before it is re-laid — higher is calmer
  variation: f32,    // @default 0.6  how far each stroke's colour wanders from the picture: hue, value and chroma, plus the odd accent stroke
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

fn pcg(v: u32) -> u32 {
  let s = v * 747796405u + 2891336453u;
  let w = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u;
  return (w >> 22u) ^ w;
}

fn u01(h: u32) -> f32 {
  return f32(h) / 4294967295.0;
}

fn h2(p: vec2f) -> f32 {
  let q = vec2i(floor(p));
  return u01(pcg((bitcast<u32>(q.x) * 1597334677u) ^ pcg(bitcast<u32>(q.y))));
}

fn vnoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(mix(h2(i), h2(i + vec2f(1.0, 0.0)), u.x),
             mix(h2(i + vec2f(0.0, 1.0)), h2(i + vec2f(1.0, 1.0)), u.x), u.y);
}

// Rotate a colour's hue about the grey axis by angle a (radians).
fn hueShift(c: vec3f, a: f32) -> vec3f {
  let k = vec3f(0.57735027);
  let ca = cos(a);
  return c * ca + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - ca);
}

fn lum(c: vec3f) -> f32 {
  return dot(c, vec3f(0.2126, 0.7152, 0.0722));
}

fn pick(px: vec2f, res: vec2f) -> vec3f {
  return textureSampleLevel(inputTexture, inputSampler, clamp(px / res, vec2f(0.0), vec2f(1.0)), 0.0).rgb;
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let res = max(frameU.resolution, vec2f(1.0));
  let px = uv * res;
  let scale = max(params.size, 0.1) * res.y / 720.0;
  let stepF = select(0.0, floor(frameU.absTime * params.fps), params.fps > 0.0);
  let stepU = u32(stepF);
  let amt = clamp(params.amount, 0.0, 1.0);

  // The sheet slips a little on every re-lay.
  let shake = (vec2f(u01(pcg(stepU * 2u + 11u)), u01(pcg(stepU * 2u + 12u))) - 0.5) * 2.0 * params.shake * scale;

  // Underpainting: the picture itself, showing through wherever no stroke lands.
  var col = pick(px + shake, res);

  // Three layers, coarse to fine: cell size, stroke length, stroke width (pixels at 720p).
  var cells = array<f32, 3>(12.0, 8.0, 5.0);
  var lens = array<f32, 3>(40.0, 28.0, 17.0);
  var wids = array<f32, 3>(8.0, 4.5, 1.8);

  for (var layer = 0u; layer < 3u; layer++) {
    let cell = cells[layer] * scale;
    let ip = floor(px / cell);
    var bestZ = -1.0;
    var bestA = 0.0;
    var bestCol = vec3f(0.0);

    for (var dy = -2; dy <= 2; dy++) {
      for (var dx = -2; dx <= 2; dx++) {
        let c = ip + vec2f(f32(dx), f32(dy));
        let ci = vec2i(c);
        let cellH = pcg((bitcast<u32>(ci.x) * 73856093u) ^ (bitcast<u32>(ci.y) * 19349663u) ^ pcg(layer * 83492791u));
        // Each stroke is re-laid on its own beat, so the drawing boils rather than flashing all at once.
        let beat = select(0u, u32(floor(frameU.absTime * params.fps / max(params.hold, 1.0) + u01(cellH))), params.fps > 0.0);
        let h = pcg(cellH ^ (beat * 2654435761u));
        let r1 = u01(pcg(h + 1u));
        let r2 = u01(pcg(h + 2u));
        let center = (c + 0.5 + (vec2f(r1, r2) - 0.5) * params.jitter) * cell;
        let len = lens[layer] * scale * (0.75 + 0.4 * u01(pcg(h + 4u)));
        let d = px - center;
        // Cheap reject before touching the picture: this stroke cannot reach this pixel.
        if (dot(d, d) > len * len * 0.3) { continue; }

        // Edge direction at the stroke's centre: strokes run ALONG edges, across the gradient.
        let e = cell * 0.6;
        let sp = center + shake;
        let baseCol = pick(sp, res);
        let l0 = lum(baseCol);
        let gx = (lum(pick(sp + vec2f(e, 0.0), res)) - l0) * 2.0;
        let gy = (lum(pick(sp + vec2f(0.0, e), res)) - l0) * 2.0;
        let gm = length(vec2f(gx, gy));

        // Fine strokes only gather where there is detail to describe.
        let need = (0.01 + 0.12 * (1.0 - clamp(params.detail, 0.0, 1.0))) * f32(layer);
        if (gm < need) { continue; }

        let flow = params.flowAngle + (vnoise(center / (220.0 * scale)) - 0.5) * 1.2;
        // Strokes run along edges.
        let edgeAng = atan2(gy, gx) + 1.5707963;
        var ang = select(flow, edgeAng, gm > 0.02);
        ang += (u01(pcg(h + 3u)) - 0.5) * 0.35 * params.jitter;

        let wid = wids[layer] * scale * (0.7 + 0.6 * u01(pcg(h + 5u)));
        let ca = cos(ang);
        let sa = sin(ang);
        let su = (ca * d.x + sa * d.y) / (len * 0.5);
        let sv = (-sa * d.x + ca * d.y) / (wid * 0.5);
        // A rounded-off bar: flat along its length, soft at both ends.
        let shape = su * su * su * su + sv * sv;
        if (shape > 1.6) { continue; }

        // Pastel streaks along the stroke, broken by the paper tooth.
        let seedOff = vec2f(f32(h & 1023u), f32((h >> 10u) & 1023u));
        let streak = vnoise(vec2f(su * len / (5.0 * scale), sv * wid / (1.1 * scale)) + seedOff);
        let a = smoothstep(1.0, 0.45, shape + (streak - 0.5) * 1.2 * params.dryness);
        let z = u01(pcg(h + 6u));
        if (a > 0.02 && z > bestZ) {
          bestZ = z;
          bestA = a;
          let tint = 1.0 + (vec3f(u01(pcg(h + 7u)), u01(pcg(h + 8u)), u01(pcg(h + 9u))) - 0.5) * 2.0 * params.colorJitter;
          var pc = baseCol * tint;
          // Pastel variation: each stick is a slightly different colour from its neighbour.
          // Open sky stays calm: flat areas get a third of the drift, edges and foliage all of it.
          let vr = clamp(params.variation, 0.0, 2.0) * mix(0.3, 1.0, smoothstep(0.0, 0.08, gm));
          pc = hueShift(pc, (u01(pcg(h + 10u)) - 0.5) * 0.7 * vr);
          let grey = vec3f(lum(pc));
          pc = mix(grey, pc, 1.0 + (u01(pcg(h + 11u)) - 0.4) * 0.6 * vr);
          pc *= 1.0 + (u01(pcg(h + 12u)) - 0.5) * 0.4 * vr;
          // Now and then an accent: a lighter, warmer or cooler stick laid over the top.
          let acc = u01(pcg(h + 13u));
          if (acc < 0.1 * vr) {
            let warm = select(-0.5, 0.5, u01(pcg(h + 14u)) > 0.5);
            pc = mix(pc, hueShift(pc, warm) * 1.5 + 0.03, 0.6);
          }
          bestCol = max(pc, vec3f(0.0)) * (0.9 + 0.2 * streak);
        }
      }
    }
    col = mix(col, bestCol, bestA * amt);
  }

  return vec4f(max(col, vec3f(0.0)), 1.0);
}
